import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';

const Navbar = () => {
  const { isAuthenticated, logout, user } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link to="/" className="logo">
          Tunisair Academy
        </Link>
        {isAuthenticated ? (
          <ul className="nav-links">
            <li><Link to="/">Tableau de bord</Link></li>
            <li><Link to="/courses">Cours</Link></li>
            {user?.role === 'admin' && (
              <li>
                <Link to="/admin" style={{
                  background: 'var(--accent-gradient-2)',
                  color: 'white',
                  padding: '10px 20px',
                  borderRadius: '25px',
                  textDecoration: 'none',
                  fontSize: '0.9rem',
                  fontWeight: '600',
                  transition: 'all 0.3s ease',
                  boxShadow: '0 4px 14px 0 rgba(240, 147, 251, 0.39)'
                }}
                onMouseEnter={(e) => {
                  e.target.style.transform = 'scale(1.05)';
                  e.target.style.boxShadow = '0 8px 25px 0 rgba(240, 147, 251, 0.5)';
                }}
                onMouseLeave={(e) => {
                  e.target.style.transform = 'scale(1)';
                  e.target.style.boxShadow = '0 4px 14px 0 rgba(240, 147, 251, 0.39)';
                }}
                >
                  Administration
                </Link>
              </li>
            )}
            <li>
              <Link to="/profile" style={{ 
                display: 'flex', 
                alignItems: 'center', 
                gap: '10px',
                textDecoration: 'none',
                color: 'white',
                padding: '10px 16px',
                borderRadius: '25px',
                transition: 'all 0.3s ease',
                backgroundColor: 'rgba(255, 255, 255, 0.15)',
                border: '1px solid rgba(255, 255, 255, 0.2)'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.25)';
                e.target.style.transform = 'scale(1.05)';
                e.target.style.borderColor = 'rgba(255, 255, 255, 0.3)';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.15)';
                e.target.style.transform = 'scale(1)';
                e.target.style.borderColor = 'rgba(255, 255, 255, 0.2)';
              }}
              >
                {user?.profile?.avatar ? (
                  <img 
                    src={user.profile.avatar.startsWith('http') 
                      ? user.profile.avatar 
                      : `http://localhost:5000${user.profile.avatar}`}
                    alt="Avatar"
                    style={{
                      width: '36px',
                      height: '36px',
                      borderRadius: '50%',
                      objectFit: 'cover',
                      border: '2px solid rgba(255, 255, 255, 0.4)',
                      boxShadow: '0 2px 8px rgba(0, 0, 0, 0.2)'
                    }}
                  />
                ) : (
                  <div style={{
                    width: '36px',
                    height: '36px',
                    borderRadius: '50%',
                    backgroundColor: 'rgba(255, 255, 255, 0.25)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '18px',
                    color: 'white',
                    fontWeight: '600',
                    border: '2px solid rgba(255, 255, 255, 0.4)'
                  }}>
                    {user?.name?.charAt(0) || 'U'}
                  </div>
                )}
                <span style={{ fontSize: '15px', fontWeight: '600' }}>
                  {user?.name || 'Profil'}
                </span>
              </Link>
            </li>
            <li>
              <button 
                onClick={handleLogout} 
                style={{ 
                  background: 'rgba(255, 255, 255, 0.1)',
                  border: '1px solid rgba(255, 255, 255, 0.2)',
                  color: 'white', 
                  cursor: 'pointer',
                  padding: '10px 16px',
                  borderRadius: '25px',
                  fontSize: '15px',
                  fontWeight: '500',
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => {
                  e.target.style.background = 'rgba(255, 255, 255, 0.2)';
                  e.target.style.transform = 'scale(1.05)';
                }}
                onMouseLeave={(e) => {
                  e.target.style.background = 'rgba(255, 255, 255, 0.1)';
                  e.target.style.transform = 'scale(1)';
                }}
              >
                Déconnexion
              </button>
            </li>
          </ul>
        ) : (
          <ul className="nav-links">
            <li>
              <Link to="/login" style={{
                background: 'rgba(255, 255, 255, 0.15)',
                color: 'white',
                padding: '10px 20px',
                borderRadius: '25px',
                textDecoration: 'none',
                fontWeight: '600',
                border: '1px solid rgba(255, 255, 255, 0.2)',
                transition: 'all 0.3s ease'
              }}
              onMouseEnter={(e) => {
                e.target.style.background = 'rgba(255, 255, 255, 0.25)';
                e.target.style.transform = 'scale(1.05)';
              }}
              onMouseLeave={(e) => {
                e.target.style.background = 'rgba(255, 255, 255, 0.15)';
                e.target.style.transform = 'scale(1)';
              }}
              >
                Connexion
              </Link>
            </li>
          </ul>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
